// ============================================================
// NOVA v1.0.0 — Orientadora y Gestora de Citas
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// RESPONSABILIDADES:
//  - Primer punto de contacto con el paciente
//  - Detección de intención y routing a SAGE o ATLAS
//  - Recopilación básica de datos para agendamiento
//  - Manejo de saludos y consultas generales
//
// NOTA: Cuando Claude API esté integrado, reemplazar la lógica
// de respuestas hardcodeadas por una llamada HTTP a la API de Claude
// con el system prompt de NOVA (ver /prompts/nova_system_prompt.md)
// ============================================================

const inp = $input.first().json;

// ── VALIDACIÓN ─────────────────────────────────────────────
const REQUIRED = ['userId', 'sessionId', 'remoteJid', 'instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing } }];
}

// ── SETUP ──────────────────────────────────────────────────
const ctx   = inp.sessionContext || {};
const nova  = ctx.nova || {};
const state = nova.state || 'welcome';
const txt   = (inp.messageText || '').toLowerCase().trim();
const intent = inp.intentDetected || '';
const ph    = inp.pendingHandoff || null;  // pendingHandoff
const fn    = inp.userName ? inp.userName.split(' ')[0] : null;
const nm    = fn ? ` ${fn}` : '';
const isNew = inp.isNewSession || ['initial', 'initial_presented'].includes(inp.sessionState);

// Mutable copies para actualizar el estado de NOVA
const novaMut = { ...nova };
let rt  = '';        // responseText
let nag = 'NOVA';   // newActiveAgent
let nss = 'active'; // newSessionState

// ============================================================
// MOTOR PRINCIPAL — Prioridades de respuesta
// Orden deliberado: handoffs > estados de recopilación >
// intenciones explícitas > saludo > primer contacto > fallback
// ============================================================

// ── PRIORIDAD 1: HANDOFFS DETECTADOS POR EL ROUTER ─────────
// El router ya detectó intención clara, NOVA solo entrega.
if (ph === 'SAGE') {
  const pre = isNew ? `¡Hola${nm}! 👋 Bienvenido/a a *Pangi*.

` : `Perfecto${nm}. `;
  rt  = `${pre}Te conecto con *SAGE* 🩺, nuestra especialista en cotizaciones médicas.\n\nYa le compartí tu mensaje — no necesitas repetir nada.\n\n¿Sobre qué procedimiento deseas cotizar?`;
  nag = 'SAGE';
  nss = 'handoff_received';
  novaMut.state = 'handoff_complete';

} else if (ph === 'ATLAS') {
  const pre = isNew ? `¡Hola${nm}! 👋 Bienvenido/a a *Pangi*.\n\n` : `Claro${nm}. `;
  rt  = `${pre}Te presento a *ATLAS* 🗺️, nuestro consejero de turismo médico.\n\nAnalizará tus opciones y calculará el costo real del viaje médico incluyendo vuelo, alojamiento y recuperación. ¿Listo/a para explorar?`;
  nag = 'ATLAS';
  nss = 'handoff_received';
  novaMut.state = 'handoff_complete';

// ── PRIORIDAD 2: RECOPILACIÓN DE DATOS — AGENDAMIENTO ──────
// NOVA está en proceso de recopilar datos para una cita.
} else if (state === 'gathering_appointment_city') {
  novaMut.appointment_city = inp.messageText;
  rt  = `Perfecto, *${inp.messageText}* 📍\n\n¿Qué *especialidad médica* necesitas?\n\nPor ejemplo: dental, cardiología, traumatología, oftalmología, dermatología...`;
  novaMut.state = 'gathering_appointment_specialty';
  nss = 'gathering_appointment_specialty';

} else if (state === 'gathering_appointment_specialty') {
  novaMut.appointment_specialty = inp.messageText;
  const city      = novaMut.appointment_city || 'la ciudad indicada';
  const specialty = inp.messageText;
  rt  = `Entendido${nm} 📋\n\n*Tu búsqueda registrada:*\n📍 Ciudad: ${city}\n🏥 Especialidad: ${specialty}\n\n⏳ La búsqueda de médicos disponibles y agendamiento en línea estarán disponibles próximamente en Pangi. Tu solicitud quedó registrada.\n\n¿En qué más puedo ayudarte?`;
  novaMut.state = 'active';
  nss = 'active';

// ── PRIORIDAD 3: INTENCIONES EXPLÍCITAS DEL ROUTER ─────────
} else if (intent.includes('agendar')) {
  rt  = `Entendido${nm}. Para encontrar médicos disponibles y agendar tu cita, necesito dos datos:\n\n*1️⃣ ¿En qué ciudad necesitas la cita?*\n\nEscríbela y seguimos.`;
  novaMut.state = 'gathering_appointment_city';
  nss = 'gathering_appointment_info';

// ── PRIORIDAD 4: PRIMER CONTACTO — SESIÓN NUEVA ────────────
} else if (isNew) {
  rt  = `¡Hola${nm}! 👋 Soy *NOVA*, tu asistente de *Pangi*.\n\nEstoy aquí para ayudarte a navegar los servicios de salud internacional. ¿Qué necesitas hoy?\n\n💰 Escribe *cotizar* — Recibe precios precisos de médicos\n🗺️ Escribe *comparar* — Analiza el costo total de tu viaje médico\n🗓️ Escribe *agendar* — Busca médicos y reserva citas\n\n¿Con cuál puedo ayudarte?`;
  novaMut.state = 'initial_presented';
  nss = 'initial_presented';

// ── PRIORIDAD 5: SALUDO EN SESIÓN ACTIVA ───────────────────
} else if (intent === 'saludo') {
  rt  = `¡Hola de nuevo${nm}! 👋 ¿En qué puedo ayudarte hoy?\n\n💰 *Cotizar* un procedimiento médico\n🗺️ *Comparar* destinos de turismo médico\n🗓️ *Agendar* una cita`;
  novaMut.state = 'active';
  nss = 'active';

// ── FALLBACK — INTENCIÓN NO RECONOCIDA ─────────────────────
} else {
  rt  = `Entiendo${nm}. Puedo orientarte en estas áreas:\n\n💰 *Cotizar* — Precios precisos de médicos para tu procedimiento\n🗺️ *Comparar destinos* — Costo total real de tu viaje médico\n🗓️ *Agendar* — Encuentra médicos disponibles en tu ciudad\n\n¿Cuál te interesa?`;
  novaMut.state = 'clarification_needed';
  nss = 'clarification_needed';
}

// ── CONSTRUIR RESPUESTA FINAL ──────────────────────────────
return [{ json: {
  success:           true,
  responseText:      rt,
  newActiveAgent:    nag,
  newSessionState:   nss,
  newSessionContext: { ...ctx, nova: novaMut },
  userId:            parseInt(inp.userId),
  sessionId:         parseInt(inp.sessionId),
  userLanguage:      inp.userLanguage || 'es',
  userName:          inp.userName     || null,
  remoteJid:         inp.remoteJid,
  instance:          inp.instance
}}];

// Pass-through: el Motor ya construyó la respuesta completa.
// Este nodo existe para claridad visual en el canvas.
return [$input.first()];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'NOVA_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
  newActiveAgent: 'NOVA',
  _meta: { timestamp: new Date().toISOString(), source: 'nova_error' }
}}];
